const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeKariba = ee.Geometry.Polygon([
    [26.8, -17.0],
    [28.5, -17.0], 
    [28.5, -16.0],
    [26.8, -16.0],
    [26.8, -17.0]
  ]);

  // 2. Data Acquisition - JRC Global Surface Water Monthly History
  const dec2018 = ee.ImageCollection('JRC/GSW1_3/MonthlyHistory')
    .filterDate('2018-12-01', '2019-01-01')
    .filterBounds(lakeKariba);

  const dec2019 = ee.ImageCollection('JRC/GSW1_3/MonthlyHistory')
    .filterDate('2019-12-01', '2020-01-01')
    .filterBounds(lakeKariba);

  // Check collection sizes
  const count2018 = dec2018.size().getInfo();
  const count2019 = dec2019.size().getInfo();

  console.log(`2018 Images: ${count2018}, 2019 Images: ${count2019}`);

  if (count2018 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const img2018 = dec2018.first();
  const img2019 = dec2019.first();

  // Calculate water area for each period
  // Water classification: 2 = water, 3 = not water
  const water2018 = img2018.eq(2);
  const water2019 = img2019.eq(2);

  // Calculate pixel counts and area
  const stats2018 = water2018.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeKariba,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeKariba,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterPixels2018 = stats2018.get('water').getInfo();
  const waterPixels2019 = stats2019.get('water').getInfo();

  console.log(`2018 Water Pixels: ${waterPixels2018}`);
  console.log(`2019 Water Pixels: ${waterPixels2019}`);

  // Check for valid pixels
  if (waterPixels2018 === 0 || waterPixels2019 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (waterPixels2018 === null || waterPixels2019 === null || 
      isNaN(waterPixels2018) || isNaN(waterPixels2019)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare water levels (higher pixel count = higher water level)
  const waterHigher2019 = waterPixels2019 > waterPixels2018;

  console.log(`Water Change: ${((waterPixels2019 - waterPixels2018) / waterPixels2018 * 100).toFixed(1)}%`);

  if (waterHigher2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
